messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Low-Poly Humanoid on Treadmill</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { overflow: hidden; background: #1a1a2e; }
  canvas { display: block; }
  #info {
    position: absolute; top: 16px; left: 50%; transform: translateX(-50%);
    font-family: 'Courier New', monospace; font-size: 14px; color: #fff;
    background: rgba(0,0,0,0.5); padding: 6px 16px; border-radius: 20px;
    pointer-events: none;
  }
</style>
</head>
<body>
<div id="info"></div>
<script type="module">
import * as THREE from './three.module.js';

// ─── Setup ───────────────────────────────────────────
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.Fog(0x1a1a2e, 12, 25);

const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 50);
camera.position.set(5, 2.2, 0);
camera.lookAt(0, 1.2, 0);

// ─── Lights ──────────────────────────────────────────
const ambientLight = new THREE.AmbientLight(0x404060, 0.6);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffeedd, 1.2);
dirLight.position.set(3, 6, 4);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(1024, 1024);
dirLight.shadow.camera.left = -4;
dirLight.shadow.camera.right = 4;
dirLight.shadow.camera.top = 4;
dirLight.shadow.camera.bottom = -1;
scene.add(dirLight);

const rimLight = new THREE.DirectionalLight(0x4488ff, 0.4);
rimLight.position.set(-3, 3, -2);
scene.add(rimLight);

// ─── Materials ───────────────────────────────────────
const skinMat = new THREE.MeshLambertMaterial({ color: 0xd4a574, flatShading: true });
const shirtMat = new THREE.MeshLambertMaterial({ color: 0x3366cc, flatShading: true });
const pantsMat = new THREE.MeshLambertMaterial({ color: 0x2a2a4a, flatShading: true });
const shoeMat = new THREE.MeshLambertMaterial({ color: 0x333333, flatShading: true });
const hairMat = new THREE.MeshLambertMaterial({ color: 0x3a2a1a, flatShading: true });
const treadmillMat = new THREE.MeshLambertMaterial({ color: 0x444455, flatShading: true });
const beltMat = new THREE.MeshLambertMaterial({ color: 0x222233, flatShading: true });
const railMat = new THREE.MeshLambertMaterial({ color: 0x556677, flatShading: true });
const groundMat = new THREE.MeshLambertMaterial({ color: 0x2a2a3a, flatShading: true });

// ─── Treadmill ───────────────────────────────────────
const treadmillGroup = new THREE.Group();

// Frame
const frameGeo = new THREE.BoxGeometry(3.2, 0.12, 1.2);
const frame = new THREE.Mesh(frameGeo, treadmillMat);
frame.position.set(0, 0.06, 0);
frame.castShadow = true;
frame.receiveShadow = true;
treadmillGroup.add(frame);

// Belt
const beltGeo = new THREE.BoxGeometry(3, 0.08, 1);
const belt = new THREE.Mesh(beltGeo, beltMat);
belt.position.set(0, 0.14, 0);
belt.receiveShadow = true;
treadmillGroup.add(belt);

// Front rail
const railGeo = new THREE.CylinderGeometry(0.03, 0.03, 1.2, 6);
const frontRail = new THREE.Mesh(railGeo, railMat);
frontRail.position.set(1.4, 0.6, 0);
frontRail.rotation.x = Math.PI / 2;
treadmillGroup.add(frontRail);

// Back rail
const backRail = new THREE.Mesh(railGeo, railMat);
backRail.position.set(-1.4, 0.6, 0);
backRail.rotation.x = Math.PI / 2;
treadmillGroup.add(backRail);

// Side supports
const supportGeo = new THREE.BoxGeometry(0.08, 0.5, 0.08);
const supportPositions = [
  [-1.4, 0.3, -0.55], [-1.4, 0.3, 0.55],
  [1.4, 0.3, -0.55], [1.4, 0.3, 0.55]
];
supportPositions.forEach(p => {
  const s = new THREE.Mesh(supportGeo, railMat);
  s.position.set(...p);
  s.castShadow = true;
  treadmillGroup.add(s);
});

// Belt rollers
const rollerGeo = new THREE.CylinderGeometry(0.08, 0.08, 0.9, 8);
const frontRoller = new THREE.Mesh(rollerGeo, treadmillMat);
frontRoller.position.set(1.35, 0.14, 0);
frontRoller.rotation.x = Math.PI / 2;
treadmillGroup.add(frontRoller);

const backRoller = new THREE.Mesh(rollerGeo, treadmillMat);
backRoller.position.set(-1.35, 0.14, 0);
backRoller.rotation.x = Math.PI / 2;
treadmillGroup.add(backRoller);

// Belt texture lines (moving segments)
const beltLines = [];
for (let i = 0; i < 8; i++) {
  const lineGeo = new THREE.BoxGeometry(0.02, 0.01, 0.9);
  const line = new THREE.Mesh(lineGeo, new THREE.MeshLambertMaterial({ color: 0x333344, flatShading: true }));
  line.position.set(-1.3 + i * 0.4, 0.18, 0);
  beltLines.push(line);
  treadmillGroup.add(line);
}

scene.add(treadmillGroup);

// ─── Ground ──────────────────────────────────────────
const groundGeo = new THREE.PlaneGeometry(20, 20);
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
ground.receiveShadow = true;
scene.add(ground);

// ─── Humanoid ────────────────────────────────────────
const humanoid = new THREE.Group();

// Helper: create limb
function createLimb(geo, mat, parent) {
  const mesh = new THREE.Mesh(geo, mat);
  mesh.castShadow = true;
  parent.add(mesh);
  return mesh;
}

// Pivot points for limbs (positioned at joint)
// ── Head ──
const headPivot = new THREE.Group();
headPivot.position.set(0, 2.0, 0);
humanoid.add(headPivot);
const headGeo = new THREE.BoxGeometry(0.28, 0.32, 0.28);
const head = createLimb(headGeo, skinMat, headPivot);
head.position.set(0, 0.16, 0);

// Hair
const hairGeo = new THREE.BoxGeometry(0.32, 0.12, 0.32);
const hair = new THREE.Mesh(hairGeo, hairMat);
hair.position.set(0, 0.32, -0.02);
hair.castShadow = true;
headPivot.add(hair);

// Eyes (simple dots)
const eyeGeo = new THREE.BoxGeometry(0.04, 0.04, 0.02);
const eyeMat = new THREE.MeshLambertMaterial({ color: 0x111111 });
const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
leftEye.position.set(0.1, 0.14, 0.14);
headPivot.add(leftEye);
const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
rightEye.position.set(-0.1, 0.14, 0.14);
headPivot.add(rightEye);

// ── Torso ──
const torsoPivot = new THREE.Group();
torsoPivot.position.set(0, 1.35, 0);
humanoid.add(torsoPivot);
const torsoGeo = new THREE.BoxGeometry(0.44, 0.55, 0.28);
const torso = createLimb(torsoGeo, shirtMat, torsoPivot);
torso.position.set(0, 0.275, 0);

// ── Upper Arms ──
const upperArmGeo = new THREE.BoxGeometry(0.1, 0.32, 0.1);

const leftUpperArmPivot = new THREE.Group();
leftUpperArmPivot.position.set(0.26, 0.5, 0);
torsoPivot.add(leftUpperArmPivot);
const leftUpperArm = createLimb(upperArmGeo, shirtMat, leftUpperArmPivot);
leftUpperArm.position.set(0, -0.16, 0);

const rightUpperArmPivot = new THREE.Group();
rightUpperArmPivot.position.set(-0.26, 0.5, 0);
torsoPivot.add(rightUpperArmPivot);
const rightUpperArm = createLimb(upperArmGeo, shirtMat, rightUpperArmPivot);
rightUpperArm.position.set(0, -0.16, 0);

// ── Lower Arms ──
const lowerArmGeo = new THREE.BoxGeometry(0.08, 0.28, 0.08);

const leftLowerArmPivot = new THREE.Group();
leftLowerArmPivot.position.set(0, -0.32, 0);
leftUpperArmPivot.add(leftLowerArmPivot);
const leftLowerArm = createLimb(lowerArmGeo, skinMat, leftLowerArmPivot);
leftLowerArm.position.set(0, -0.14, 0);

const rightLowerArmPivot = new THREE.Group();
rightLowerArmPivot.position.set(0, -0.32, 0);
rightUpperArmPivot.add(rightLowerArmPivot);
const rightLowerArm = createLimb(lowerArmGeo, skinMat, rightLowerArmPivot);
rightLowerArm.position.set(0, -0.14, 0);

// ── Upper Legs ──
const upperLegGeo = new THREE.BoxGeometry(0.14, 0.4, 0.14);

const leftUpperLegPivot = new THREE.Group();
leftUpperLegPivot.position.set(0.12, -0.05, 0);
torsoPivot.add(leftUpperLegPivot);
const leftUpperLeg = createLimb(upperLegGeo, pantsMat, leftUpperLegPivot);
leftUpperLeg.position.set(0, -0.2, 0);

const rightUpperLegPivot = new THREE.Group();
rightUpperLegPivot.position.set(-0.12, -0.05, 0);
torsoPivot.add(rightUpperLegPivot);
const rightUpperLeg = createLimb(upperLegGeo, pantsMat, rightUpperLegPivot);
rightUpperLeg.position.set(0, -0.2, 0);

// ── Lower Legs ──
const lowerLegGeo = new THREE.BoxGeometry(0.12, 0.36, 0.12);

const leftLowerLegPivot = new THREE.Group();
leftLowerLegPivot.position.set(0, -0.4, 0);
leftUpperLegPivot.add(leftLowerLegPivot);
const leftLowerLeg = createLimb(lowerLegGeo, pantsMat, leftLowerLegPivot);
leftLowerLeg.position.set(0, -0.18, 0);

const rightLowerLegPivot = new THREE.Group();
rightLowerLegPivot.position.set(0, -0.4, 0);
rightUpperLegPivot.add(rightLowerLegPivot);
const rightLowerLeg = createLimb(lowerLegGeo, pantsMat, rightLowerLegPivot);
rightLowerLeg.position.set(0, -0.18, 0);

// ── Feet ──
const footGeo = new THREE.BoxGeometry(0.12, 0.08, 0.22);

const leftFootPivot = new THREE.Group();
leftFootPivot.position.set(0, -0.36, 0);
leftLowerLegPivot.add(leftFootPivot);
const leftFoot = createLimb(footGeo, shoeMat, leftFootPivot);
leftFoot.position.set(0, -0.04, 0.05);

const rightFootPivot = new THREE.Group();
rightFootPivot.position.set(0, -0.36, 0);
rightLowerLegPivot.add(rightFootPivot);
const rightFoot = createLimb(footGeo, shoeMat, rightFootPivot);
rightFoot.position.set(0, -0.04, 0.05);

scene.add(humanoid);

// ─── Animation State ─────────────────────────────────
const CYCLE_DURATION = 10; // seconds
const STATE_STILL = 0;
const STATE_WALK = 1;
const STATE_RUN = 2;

function getState(t) {
  const cycleT = t % CYCLE_DURATION;
  if (cycleT < 2) return STATE_STILL;
  if (cycleT < 5) return STATE_WALK;
  return STATE_RUN;
}

function getPhase(t) {
  const state = getState(t);
  if (state === STATE_STILL) return 0;
  if (state === STATE_WALK) {
    return (t % CYCLE_DURATION - 2) / 3; // 0..1 during walk
  }
  return (t % CYCLE_DURATION - 5) / 3; // 0..1 during run
}

function getPhaseTime(t) {
  const state = getState(t);
  if (state === STATE_STILL) return 0;
  if (state === STATE_WALK) return t % CYCLE_DURATION - 2;
  return t % CYCLE_DURATION - 5;
}

const infoEl = document.getElementById('info');

// ─── Animation Loop ──────────────────────────────────
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const elapsed = clock.getElapsedTime();
  const t = elapsed;

  const state = getState(t);
  const pt = getPhaseTime(t);

  // Update info
  const stateNames = ['STANDING', 'WALKING', 'RUNNING'];
  infoEl.textContent = stateNames[state];

  // ── Walking parameters ──
  const walkFrequency = 2.0; // Hz
  const walkLegAmplitude = 0.45; // radians
  const walkArmAmplitude = 0.55; // radians
  const walkBounceAmplitude = 0.02; // meters

  // ── Running parameters ──
  const runFrequency = 3.2; // Hz
  const runLegAmplitude = 0.85; // radians
  const runArmAmplitude = 0.95; // radians
  const runBounceAmplitude = 0.06; // meters
  const runLeanAngle = 0.12; // radians forward lean

  // Interpolate parameters
  let legAmp, armAmp, bounceAmp, freq, leanAngle;

  if (state === STATE_STILL) {
    legAmp = 0;
    armAmp = 0;
    bounceAmp = 0;
    freq = 0;
    leanAngle = 0;
  } else if (state === STATE_WALK) {
    legAmp = walkLegAmplitude;
    armAmp = walkArmAmplitude;
    bounceAmp = walkBounceAmplitude;
    freq = walkFrequency;
    leanAngle = 0;
  } else {
    legAmp = runLegAmplitude;
    armAmp = runArmAmplitude;
    bounceAmp = runBounceAmplitude;
    freq = runFrequency;
    leanAngle = runLeanAngle;
  }

  // Phase angle for limb oscillation
  const phase = pt * freq * 2 * Math.PI;

  // ── Body bounce ──
  const bounce = bounceAmp * Math.abs(Math.sin(phase));

  // ── Torso lean ──
  torsoPivot.rotation.x = -leanAngle;

  // ── Head bob ──
  headPivot.position.y = 2.0 + bounce * 0.5;
  headPivot.rotation.x = -leanAngle * 0.3;

  // ── Left leg ──
  // Upper leg swing
  const leftLegAngle = Math.sin(phase) * legAmp;
  leftUpperLegPivot.rotation.x = leftLegAngle;

  // Lower leg bend (knee)
  // When leg swings forward, knee bends slightly; when back, it bends more
  const leftKneeBend = Math.max(0, -Math.sin(phase)) * legAmp * 0.5 + 0.05;
  leftLowerLegPivot.rotation.x = -leftKneeBend;

  // Foot angle
  const leftFootAngle = Math.sin(phase) * legAmp * 0.3;
  leftFootPivot.rotation.x = leftFootAngle;

  // ── Right leg ──
  const rightLegAngle = Math.sin(phase + Math.PI) * legAmp;
  rightUpperLegPivot.rotation.x = rightLegAngle;

  const rightKneeBend = Math.max(0, -Math.sin(phase + Math.PI)) * legAmp * 0.5 + 0.05;
  rightLowerLegPivot.rotation.x = -rightKneeBend;

  const rightFootAngle = Math.sin(phase + Math.PI) * legAmp * 0.3;
  rightFootPivot.rotation.x = rightFootAngle;

  // ── Left arm ──
  const leftArmAngle = Math.sin(phase + Math.PI) * armAmp;
  leftUpperArmPivot.rotation.x = leftArmAngle;

  // Elbow bend
  const leftElbowBend = Math.max(0, Math.sin(phase + Math.PI)) * armAmp * 0.4 + 0.15;
  leftLowerArmPivot.rotation.x = -leftElbowBend;

  // ── Right arm ──
  const rightArmAngle = Math.sin(phase) * armAmp;
  rightUpperArmPivot.rotation.x = rightArmAngle;

  const rightElbowBend = Math.max(0, Math.sin(phase)) * armAmp * 0.4 + 0.15;
  rightLowerArmPivot.rotation.x = -rightElbowBend;

  // ── Subtle body sway ──
  if (state !== STATE_STILL) {
    const sway = Math.sin(phase) * 0.02;
    torsoPivot.rotation.z = sway;
    headPivot.rotation.z = sway * 0.5;
  } else {
    torsoPivot.rotation.z = 0;
    headPivot.rotation.z = 0;
  }

  // ── Treadmill belt movement ──
  if (state !== STATE_STILL) {
    const speed = state === STATE_RUN ? 0.8 : 0.4;
    beltLines.forEach((line, i) => {
      let x = -1.3 + i * 0.4;
      x += speed * 0.02;
      if (x > 1.3) x -= 3.2;
      line.position.x = x;
    });

    // Rotate rollers
    const rollerSpeed = state === STATE_RUN ? 0.15 : 0.08;
    frontRoller.rotation.z += rollerSpeed;
    backRoller.rotation.z -= rollerSpeed;
  }

  renderer.render(scene, camera);
}

animate();

// ─── Resize ──────────────────────────────────────────
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});
</script>
</body>
</html>
```
